; banks.asm -- chapter 48: the mappers measured
; generated by gen48.py
        INCLUDE "msx.inc"
        OUTPUT "banks.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
SSLOT   EQU $FFFF               ; the secondary slot register, in page 3
RUN_AT  EQU $C100               ; where the program runs
RESULTS EQU $C400               ; 4 bytes a write, and 4 before any
; The mappers measured: each 8 KB block of this cartridge holds its number
; in its last byte. The program, copied to the RAM, reads the four 8 KB
; windows of pages 1 and 2 at the start, then after each write of a list.
init:   di
        ld sp, SYS_AREA
        call here               ; page 1's slot: the cartridge
        call setpage2           ; page 2 shows it too
        ld hl, probe            ; the program into the RAM
        ld de, RUN_AT
        ld bc, probe_end - probe
        ldir
        jp RUN_AT

; here: -> A = the slot ID of page 1, where INIT runs: the primary slot from
; port $A8 and, if EXPTBL says it is expanded, the secondary from the
; slot's own register. The interrupts must be off. Uses A, BC, HL
here:   in a, (PPI_A)           ; 12
        rrca                    ;  5
        rrca                    ;  5
        and 3                   ;  8  page 1's primary slot
        ld c, a                 ;  5
        ld b, 0                 ;  8
        ld hl, EXPTBL           ; 11
        add hl, bc              ; 12
        or (hl)                 ;  8  bit 7 if the slot is expanded
        ret p                   ; 12, or 6  it is not: that is the ID
        ld l, a                 ;  5  1000 00PP
        and 3                   ;  8
        call subreg             ; 18  the slot's register
        and %00001100           ;  8  page 1's secondary slot
        or l                    ;  5
        ret                     ; 11

; setpage2: A = a slot ID -> page 2 shows that slot: its primary slot in
; port $A8 and, for an expanded slot, its secondary slot in the slot's
; register, written at $FFFF through page 3 and copied into SLTTBL for the
; BIOS. The interrupts must be off. Uses A, BC, DE, HL
setpage2: ld e, a               ;  5  the slot ID
        and 3                   ;  8
        rrca                    ;  5
        rrca                    ;  5
        ld d, a                 ;  5  the primary slot in bits 6-7
        rrca                    ;  5
        rrca                    ;  5
        ld b, a                 ;  5  and in bits 4-5
        in a, (PPI_A)           ; 12
        ld c, a                 ;  5  the slots as they are
        bit 7, e                ; 10  expanded?
        jr z, .primary          ; 13, or 8
        and $3F                 ;  8
        or d                    ;  5
        out (PPI_A), a          ; 12  page 3 shows the slot: no RAM
        ld a, (SSLOT)           ; 14
        cpl                     ;  5  its register, as it stands
        and %11001111           ;  8  page 2's secondary slot cleared
        ld d, a                 ;  5
        ld a, e                 ;  5
        and %00001100           ;  8  the new one, in bits 2-3
        rlca                    ;  5
        rlca                    ;  5  and in bits 4-5
        or d                    ;  5
        ld (SSLOT), a           ; 14  written
        ld d, a                 ;  5
        ld a, c                 ;  5
        out (PPI_A), a          ; 12  page 3 back: the RAM again
        ld a, e                 ;  5
        and 3                   ;  8
        add a, low SLTTBL       ;  8
        ld l, a                 ;  5
        ld h, high SLTTBL       ;  8
        ld (hl), d              ;  8  SLTTBL for that slot, as the BIOS keeps it
.primary: ld a, c               ;  5
        and %11001111           ;  8  page 2's primary slot cleared
        or b                    ;  5  and set
        out (PPI_A), a          ; 12
        ret                     ; 11

; subreg: A = an expanded primary slot -> A = its secondary slot register,
; read at $FFFF through page 3, which hands it back complemented. The
; interrupts must be off: while page 3 shows that slot the RAM is gone, and
; the stack with it. Uses A, B, C
subreg: rrca                    ;  5
        rrca                    ;  5  the slot into bits 6-7
        ld b, a                 ;  5
        in a, (PPI_A)           ; 12
        ld c, a                 ;  5  the slots as they are
        and $3F                 ;  8
        or b                    ;  5
        out (PPI_A), a          ; 12  page 3 shows the slot: no RAM
        ld a, (SSLOT)           ; 14  its register, complemented
        cpl                     ;  5
        ld b, a                 ;  5
        ld a, c                 ;  5
        out (PPI_A), a          ; 12  page 3 back: the RAM again
        ld a, b                 ;  5
        ret                     ; 11

probe:                          ; assembled for the RAM it runs in
        DISP RUN_AT
run:    ld hl, RESULTS
        call look               ; the windows before any write
        ld ix, tests
        ld b, 12
.test:  ld e, (ix+0)
        ld d, (ix+1)            ; DE: the address
        ld a, (ix+2)            ; A: the value
        ld (de), a              ; written
        call look               ; and the windows after it
        inc ix
        inc ix
        inc ix
        djnz .test
done:   jr done

; look: the block each 8 KB of pages 1 and 2 shows, read at its last byte, to HL
look:   ld a, ($5FFF)
        ld (hl), a
        inc hl
        ld a, ($7FFF)
        ld (hl), a
        inc hl
        ld a, ($9FFF)
        ld (hl), a
        inc hl
        ld a, ($BFFF)
        ld (hl), a
        inc hl
        ret
tests:  dw $6000
        db 3
        dw $6800
        db 4
        dw $7000
        db 5
        dw $77FF
        db 6
        dw $7800
        db 7
        dw $77FF
        db 9
        dw $77FF
        db 255
        dw $5000
        db 9
        dw $9000
        db 10
        dw $B000
        db 11
        dw $8000
        db 12
        dw $A000
        db 13
        ENT
probe_end:
        ASSERT $ <= $5FFF, the program must leave block 0's last byte
        ds $5FFF - $, $FF
        db 0                    ; block 0's number
        ds $7FFF - $, $FF
        db 1                    ; block 1's
        OUTEND
        OUTPUT "banks.rom", a   ; blocks 2 and 3
        ORG $8000
        ds $9FFF - $, $FF
        db 2
        ds $BFFF - $, $FF
        db 3
        OUTEND
        OUTPUT "banks.rom", a   ; blocks 4 and 5
        ORG $8000
        ds $9FFF - $, $FF
        db 4
        ds $BFFF - $, $FF
        db 5
        OUTEND
        OUTPUT "banks.rom", a   ; blocks 6 and 7
        ORG $8000
        ds $9FFF - $, $FF
        db 6
        ds $BFFF - $, $FF
        db 7
        OUTEND
        OUTPUT "banks.rom", a   ; blocks 8 and 9
        ORG $8000
        ds $9FFF - $, $FF
        db 8
        ds $BFFF - $, $FF
        db 9
        OUTEND
        OUTPUT "banks.rom", a   ; blocks 10 and 11
        ORG $8000
        ds $9FFF - $, $FF
        db 10
        ds $BFFF - $, $FF
        db 11
        OUTEND
        OUTPUT "banks.rom", a   ; blocks 12 and 13
        ORG $8000
        ds $9FFF - $, $FF
        db 12
        ds $BFFF - $, $FF
        db 13
        OUTEND
        OUTPUT "banks.rom", a   ; blocks 14 and 15
        ORG $8000
        ds $9FFF - $, $FF
        db 14
        ds $BFFF - $, $FF
        db 15
